Q: Selecting all text in HTML text input when clicked A: <p>The answers listed are partial according to me. I have linked below two examples of how to do this in Angular and with jQuery.</p>
<p><strong>This solution has the following features:</strong></p>
<ul>
<li>Works for all browsers that support JQuery, Safari, Chrome, IE, Firefox, etc.</li>
<li>Works for Phonegap/Cordova: Android and iOS.</li>
<li>Only selects all once after input gets focus until next blur and then focus</li>
<li>Multiple inputs can be used and it does not glitch out.</li>
<li>Angular directive has great re-usage simply add directive select-all-on-click</li>
<li>JQuery can be modified easily</li>
</ul>
<p><strong>JQuery:</strong>
<a href="http://plnkr.co/edit/VZ0o2FJQHTmOMfSPRqpH?p=preview" rel="nofollow noreferrer">http://plnkr.co/edit/VZ0o2FJQHTmOMfSPRqpH?p=preview</a></p>
<pre><code>$(&quot;input&quot;).blur(function() {
  if ($(this).attr(&quot;data-selected-all&quot;)) {
    //Remove atribute to allow select all again on focus        
    $(this).removeAttr(&quot;data-selected-all&quot;);
  }
});

$(&quot;input&quot;).click(function() {
  if (!$(this).attr(&quot;data-selected-all&quot;)) {
    try {
      $(this).selectionStart = 0;
      $(this).selectionEnd = $(this).value.length + 1;
      //add atribute allowing normal selecting post focus
      $(this).attr(&quot;data-selected-all&quot;, true);
    } catch (err) {
      $(this).select();
      //add atribute allowing normal selecting post focus
      $(this).attr(&quot;data-selected-all&quot;, true);
    }
  }
});
</code></pre>
<p><strong>Angular:</strong>
<a href="http://plnkr.co/edit/llcyAf?p=preview" rel="nofollow noreferrer">http://plnkr.co/edit/llcyAf?p=preview</a></p>
<pre><code>var app = angular.module('app', []);
//add select-all-on-click to any input to use directive
app.directive('selectAllOnClick', [function() {
  return {
    restrict: 'A',
    link: function(scope, element, attrs) {
      var hasSelectedAll = false;
      element.on('click', function($event) {
        if (!hasSelectedAll) {
          try {
            //iOS, Safari, thows exception on Chrome etc
            this.selectionStart = 0;
            this.selectionEnd = this.value.length + 1;
            hasSelectedAll = true;
          } catch (err) {
            //Non iOS option if not supported, e.g. Chrome
            this.select();
            hasSelectedAll = true;
          }
        }
      });
      //On blur reset hasSelectedAll to allow full select
      element.on('blur', function($event) {
        hasSelectedAll = false;
      });
    }
  };
}]);
</code></pre>
